"""Programmatic builders for synthetic Ren'Py game directories (test fixtures only).

Nothing in this module is product code. The fake ``renpy`` modules are installed into
``sys.modules`` only while a fixture ``.rpyc`` is being pickled, so that the bytes have the same
shape as real compiled scripts:

* AST nodes pickle as ``NEWOBJ(cls, ())`` followed by ``BUILD((None, slots_dict))``;
* ``PyCode`` pickles with a tuple state ``(1, source, location, mode, py, ...)``;
* ``PyExpr`` pickles as ``NEWOBJ`` with constructor args (Ren'Py 8.1 style, ``renpy.ast``) or as
  ``REDUCE`` (Ren'Py 8.4 style, ``renpy.astsupport``).

Product code never imports these fake modules.
"""

from __future__ import annotations

import contextlib
import copyreg
import io
import json
import pickle
import random
import shutil
import struct
import sys
import types
import zipfile
import zlib
from collections import defaultdict
from collections.abc import Iterator
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

RPA_KEY = 0x42424242
ZIP_TIME = (2026, 1, 1, 0, 0, 0)


# --------------------------------------------------------------------------------- statements


@dataclass
class Define:
    """``define <store>.<name> <op> <expr>`` (``default`` when ``kind == "default"``)."""

    store: str
    name: str
    expr: str
    op: str = "="
    kind: str = "define"


@dataclass
class PythonBlock:
    """``python early:`` or ``init [N] python:`` block; ``body`` is dedented source."""

    body: str
    early: bool = False
    init: int = 0


Statement = Define | PythonBlock


def options_stmts(
    *,
    name: str | None = "Fixture Game",
    version: str | None = "1.0",
    build_name: str | None = "FixtureGame",
    save_directory: str | None = "FixtureGame-1600000000",
    extra: list[Statement] | None = None,
) -> list[Statement]:
    """Statements shaped like a launcher-generated ``options.rpy``."""
    stmts: list[Statement] = []
    if name is not None:
        stmts.append(Define("config", "name", f"_({json.dumps(name)})"))
    stmts.append(Define("gui", "show_name", "True"))
    if version is not None:
        stmts.append(Define("config", "version", json.dumps(version)))
    stmts.append(Define("config", "has_sound", "True"))
    if build_name is not None:
        stmts.append(Define("build", "name", json.dumps(build_name)))
    if save_directory is not None:
        stmts.append(Define("config", "save_directory", json.dumps(save_directory)))
    stmts.append(Define("config", "window_icon", '"gui/window_icon.png"'))
    stmts.append(PythonBlock("build.classify('**~', None)\nbuild.documentation('*.html')"))
    stmts.extend(extra or [])
    return stmts


def script_stmts() -> list[Statement]:
    """A non-options script that defines nothing EngineSave cares about."""
    return [
        Define("store", "e", 'Character("Eileen")'),
        Define("persistent", "seen_intro", "False", kind="default"),
    ]


def render_rpy(stmts: list[Statement]) -> tuple[str, list[int]]:
    """Render statements as ``.rpy`` text; also return each statement's 1-based line number."""
    lines = ["## Synthetic script generated by tests/fixtures/builder.py", ""]
    numbers: list[int] = []
    for st in stmts:
        numbers.append(len(lines) + 1)
        if isinstance(st, Define):
            store = "" if st.store == "store" else f"{st.store}."
            lines.extend(f"{st.kind} {store}{st.name} {st.op} {st.expr}".split("\n"))
        else:
            if st.early:
                lines.append("python early:")
            elif st.init:
                lines.append(f"init {st.init} python:")
            else:
                lines.append("init python:")
            lines.extend(("    " + ln) if ln.strip() else "" for ln in st.body.split("\n"))
        lines.append("")
    return "\n".join(lines) + "\n", numbers


# ------------------------------------------------------------------------- fake renpy modules


class _FakeNode:
    """Pickles like a Ren'Py AST node: ``NEWOBJ(cls, ())`` + ``BUILD((None, state))``."""

    def __init__(self, **state: object) -> None:
        self.state = state

    def __reduce_ex__(self, protocol: object) -> tuple[object, ...]:
        return (copyreg.__newobj__, (type(self),), (None, dict(self.state)))


class _FakePyCode:
    """Pickles like ``renpy.ast.PyCode``: ``NEWOBJ(cls, ())`` + ``BUILD(tuple_state)``."""

    def __init__(self, source: str, filename: str, line: int, mode: str, style: str) -> None:
        self.source = source
        self.location = (filename, line)
        self.mode = mode
        self.style = style

    def __reduce_ex__(self, protocol: object) -> tuple[object, ...]:
        if self.style == "8.4":
            state: tuple[object, ...] = (1, self.source, self.location, self.mode, 3, 1651194256, 0)
        else:
            state = (1, self.source, self.location, self.mode, 3)
        return (copyreg.__newobj__, (type(self),), state)


class _FakePyExprNewobj(str):
    """Ren'Py 8.1 style ``PyExpr``: ``NEWOBJ(cls, (s, filename, line, py))`` + slot state."""

    filename: str
    linenumber: int

    def __new__(cls, s: str, filename: str, linenumber: int) -> _FakePyExprNewobj:
        self = str.__new__(cls, s)
        self.filename = filename
        self.linenumber = linenumber
        return self

    def __reduce_ex__(self, protocol: object) -> tuple[object, ...]:
        args = (type(self), str(self), self.filename, self.linenumber, 3)
        state = {"filename": self.filename, "linenumber": self.linenumber, "py": 3}
        return (copyreg.__newobj__, args, (None, state))


class _FakePyExprReduce(str):
    """Ren'Py 8.4 style ``PyExpr``: ``REDUCE(cls, (s, filename, line, py, hash, col))``."""

    filename: str
    linenumber: int

    def __new__(cls, s: str, filename: str, linenumber: int) -> _FakePyExprReduce:
        self = str.__new__(cls, s)
        self.filename = filename
        self.linenumber = linenumber
        return self

    def __reduce_ex__(self, protocol: object) -> tuple[object, ...]:
        return (type(self), (str(self), self.filename, self.linenumber, 3, 1651194256, 21))


def _named(base: type, module: str, name: str) -> type:
    return type(name, (base,), {"__module__": module, "__qualname__": name})


_PKG = types.ModuleType("renpy")
_PKG.__path__ = []
_AST = types.ModuleType("renpy.ast")
_SUPPORT = types.ModuleType("renpy.astsupport")
for _node_name in ("Init", "Define", "Default", "Python", "EarlyPython", "Label"):
    setattr(_AST, _node_name, _named(_FakeNode, "renpy.ast", _node_name))
_AST.PyCode = _named(_FakePyCode, "renpy.ast", "PyCode")
_AST.PyExpr = _named(_FakePyExprNewobj, "renpy.ast", "PyExpr")
_SUPPORT.PyExpr = _named(_FakePyExprReduce, "renpy.astsupport", "PyExpr")
_PKG.ast = _AST
_PKG.astsupport = _SUPPORT
_FAKE_MODULES = {"renpy": _PKG, "renpy.ast": _AST, "renpy.astsupport": _SUPPORT}


@contextlib.contextmanager
def fake_renpy_modules() -> Iterator[None]:
    """Temporarily expose the fake modules so ``pickle`` can reference their classes."""
    saved = {name: sys.modules.get(name) for name in _FAKE_MODULES}
    sys.modules.update(_FAKE_MODULES)
    try:
        yield
    finally:
        for name, previous in saved.items():
            if previous is None:
                sys.modules.pop(name, None)
            else:
                sys.modules[name] = previous


def build_ast(stmts: list[Statement], filename: str, style: str) -> tuple[object, list[object]]:
    """Build ``(data_dict, statements)`` with the same object graph shape Ren'Py pickles."""
    _, numbers = render_rpy(stmts)
    expr_cls = _SUPPORT.PyExpr if style == "8.4" else _AST.PyExpr
    nodes: list[object] = []
    for st, line in zip(stmts, numbers, strict=True):
        if isinstance(st, Define):
            code = _AST.PyCode(expr_cls(st.expr, filename, line), filename, line, "eval", style)
            state: dict[str, object] = {
                "linenumber": line,
                "filename": filename,
                "store": "store" if st.store == "store" else f"store.{st.store}",
                "varname": st.name,
                "code": code,
            }
            if style == "8.1":
                state["operator"] = st.op
                state["index"] = None
            elif st.op != "=":
                state["operator"] = st.op
            node_cls = _AST.Default if st.kind == "default" else _AST.Define
            block = [node_cls(**state)]
            nodes.append(_AST.Init(linenumber=line, filename=filename, block=block, priority=0))
        else:
            source = expr_cls(st.body, filename, line + 1)
            code = _AST.PyCode(source, filename, line + 1, "exec", style)
            common = {"linenumber": line, "filename": filename, "code": code, "hide": False}
            if st.early:
                nodes.append(_AST.EarlyPython(**common, store="store"))
            else:
                block = [_AST.Python(**common, store="store")]
                nodes.append(
                    _AST.Init(linenumber=line, filename=filename, block=block, priority=st.init)
                )
    data = {"version": 5003000, "key": "unlocked", "deferred_parse_errors": defaultdict(list)}
    return data, nodes


def rpyc_container(payload: bytes, copies: int = 2, header: bytes = b"RENPY RPC2") -> bytes:
    """Wrap a zlib-compressed pickle in an RPYC2 slot table (slot 2.. are copies of slot 1);
    ``header`` replaces the magic, as some packing tools do (D50: ``b"chengf 2"``)."""
    start = len(header) + 12 * (copies + 1)
    table = b"".join(
        struct.pack("<III", slot, start + (slot - 1) * len(payload), len(payload))
        for slot in range(1, copies + 1)
    )
    return header + table + struct.pack("<III", 0, 0, 0) + payload * copies


def rpyc_bytes(
    stmts: list[Statement], filename: str, style: str = "8.1", header: bytes = b"RENPY RPC2"
) -> bytes:
    """Compile statements to RPYC2 bytes: protocol 2 for 8.1 style, protocol 5 for 8.4."""
    tree = build_ast(stmts, filename, style)
    with fake_renpy_modules():
        raw = pickle.dumps(tree, protocol=5 if style == "8.4" else 2)
    return rpyc_container(zlib.compress(raw), header=header)


def rpa_bytes(members: dict[str, bytes], *, version: str = "3.0", key: int = RPA_KEY) -> bytes:
    """Build an RPA-3.0 (XOR-obfuscated, 3-tuple) or RPA-2.0 (plain 2-tuple) archive."""
    header_len = 34 if version == "3.0" else 25
    body = io.BytesIO()
    index: dict[str, list[tuple[object, ...]]] = {}
    offset = header_len
    for name, data in members.items():
        if version == "3.0":
            index[name] = [(offset ^ key, len(data) ^ key, b"")]
        else:
            index[name] = [(offset, len(data))]
        body.write(data)
        offset += len(data)
    if version == "3.0":
        header = b"RPA-3.0 %016x %08x\n" % (offset, key)
    else:
        header = b"RPA-2.0 %016x\n" % offset
    assert len(header) == header_len
    return header + body.getvalue() + zlib.compress(pickle.dumps(index, protocol=2))


# ------------------------------------------------------------------------------- save files


def _zip_member(zf: zipfile.ZipFile, name: str, data: bytes | str) -> None:
    zf.writestr(zipfile.ZipInfo(name, date_time=ZIP_TIME), data)


def save_bytes(version: str | None = "1.0", *, seed: int = 0, name: str = "") -> bytes:
    """A Ren'Py-like ``.save`` zip: ``json`` (with ``_version``), ``log``, ``renpy_version``."""
    rng = random.Random(seed)
    meta: dict[str, object] = {"_renpy_version": [8, 1, 3, 23091805], "_save_name": name}
    if version is not None:
        meta["_version"] = version
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        _zip_member(zf, "json", json.dumps(meta))
        _zip_member(zf, "log", rng.randbytes(256))
        _zip_member(zf, "renpy_version", "8.1.3.23091805")
        _zip_member(zf, "screenshot.png", b"\x89PNG\r\n\x1a\n" + rng.randbytes(32))
    return buf.getvalue()


def persistent_bytes(seed: int = 0) -> bytes:
    return zlib.compress(b"fake persistent %d" % seed)


SAVE_NAMES = ["1-1-LT1.save", "1-2-LT1.save", "auto-1-LT1.save", "quick-1-LT1.save"]


def save_set(count: int, version: str | None = "1.0", *, seed: int = 0) -> dict[str, bytes]:
    """``count`` slot saves (cycling through realistic names) plus ``persistent``."""
    files: dict[str, bytes] = {}
    for i in range(count):
        base = SAVE_NAMES[i % len(SAVE_NAMES)]
        name = base if i < len(SAVE_NAMES) else f"2-{i}-LT1.save"
        files[name] = save_bytes(version, seed=seed + i, name=f"slot {i}")
    files["persistent"] = persistent_bytes(seed)
    return files


def write_files(directory: Path, files: dict[str, bytes]) -> None:
    for rel, data in files.items():
        path = directory / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)


def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.encode("utf-8"))


# ------------------------------------------------------------------------------- game trees


@dataclass
class GameSpec:
    dir_name: str
    exe: str
    stmts: list[Statement] = field(default_factory=options_stmts)
    save_directory: str | None = "FixtureGame-1600000000"
    style: str = "8.1"
    engine_version: str = "8.1.3.23091805"
    loose_rpy: bool = True
    loose_rpyc: bool = True
    rpa_scripts: bool = False
    local_saves: int = 3
    global_saves: int | None = None
    save_version: str = "1.0"
    gamedir_name: str = "game"
    lib: bool = True
    options: bool = True  # False: no options script at all (no metadata)
    rpyc_stmts: list[Statement] | None = None  # options.rpyc differs from options.rpy (stale .rpy)
    rpyc_header: bytes = b"RENPY RPC2"  # D50: a packing tool may rename the magic
    # 0.9.0 (D52): more scripts beside options and script, by stem; and filler scripts
    extra_scripts: dict[str, list[Statement]] = field(default_factory=dict)
    script_count: int = 0  # filler scripts chapter_0001... without any config
    rpa_name: str = "archive.rpa"  # D53: an archive under another name (archive.liu)
    options_dir: str = ""  # 0.10.0 (D60 1): options in this folder below game/, not at the top


@dataclass
class BuiltGame:
    spec: GameSpec
    root: Path
    gamedir: Path
    local_dir: Path
    global_dir: Path | None
    local_files: dict[str, bytes]
    global_files: dict[str, bytes]


def build_engine_skeleton(root: Path, exe: str, engine_version: str, *, lib: bool = True) -> None:
    """Launcher stubs (never executed), ``renpy/`` with ``vc_version.py``, optional ``lib/``."""
    write_text(root / f"{exe}.exe", "MZ synthetic launcher stub; never executed\n")
    write_text(root / f"{exe}.py", "# Synthetic launcher stub; never executed by the tests.\n")
    write_text(root / f"{exe}.sh", "#!/bin/sh\n# Synthetic launcher stub.\n")
    write_text(root / "renpy" / "__init__.py", "# synthetic\n")
    vc = f"branch = 'fix'\nnightly = False\nofficial = True\nversion = '{engine_version}'\n"
    write_text(root / "renpy" / "vc_version.py", vc + "version_name = 'Synthetic'\n")
    (root / "renpy" / "common").mkdir(parents=True, exist_ok=True)
    if lib:
        (root / "lib" / "py3-windows-x86_64").mkdir(parents=True, exist_ok=True)


def build_game(parent: Path, spec: GameSpec, saves_root: Path | None) -> BuiltGame:
    root = parent / spec.dir_name
    build_engine_skeleton(root, spec.exe, spec.engine_version, lib=spec.lib)
    gamedir = root / spec.gamedir_name
    gamedir.mkdir(parents=True, exist_ok=True)
    major_minor = ", ".join(spec.engine_version.split(".")[:3])
    write_text(gamedir / "script_version.txt", f"({major_minor})")

    options_stem = f"{spec.options_dir}/options" if spec.options_dir else "options"
    scripts = {options_stem: spec.stmts, "script": script_stmts(), **spec.extra_scripts}
    if not spec.options:
        del scripts[options_stem]
    filler = script_stmts()
    scripts.update({f"chapter_{i:04d}": filler for i in range(1, spec.script_count + 1)})
    archive: dict[str, bytes] = {}
    for stem, stmts in scripts.items():
        text, _ = render_rpy(stmts)
        (gamedir / stem).parent.mkdir(parents=True, exist_ok=True)  # a stem may have folders
        if spec.loose_rpy:
            write_text(gamedir / f"{stem}.rpy", text)
        if spec.loose_rpyc:
            compiled = spec.rpyc_stmts if stem == options_stem and spec.rpyc_stmts else stmts
            data = rpyc_bytes(compiled, f"game/{stem}.rpy", spec.style, spec.rpyc_header)
            (gamedir / f"{stem}.rpyc").write_bytes(data)
        if spec.rpa_scripts:
            archive[f"{stem}.rpy"] = text.encode("utf-8")
    if archive:
        archive["images/bg room.png"] = b"\x89PNG\r\n\x1a\nsynthetic image"
        (gamedir / spec.rpa_name).write_bytes(rpa_bytes(archive))

    local_dir = gamedir / "saves"
    local_files = save_set(spec.local_saves, spec.save_version) if spec.local_saves else {}
    write_files(local_dir, local_files)

    global_dir: Path | None = None
    global_files: dict[str, bytes] = {}
    if saves_root is not None and spec.save_directory:
        count = spec.local_saves if spec.global_saves is None else spec.global_saves
        if count:
            base = save_set(count, spec.save_version)
            global_files = {**base, **{f"sync/{k}": v for k, v in base.items()}}
            global_dir = saves_root / spec.save_directory
            write_files(global_dir, global_files)
    return BuiltGame(spec, root, gamedir, local_dir, global_dir, local_files, global_files)


# ---------------------------------------------------------------------------- fixture matrix


def build_f1(games_root: Path, saves_root: Path) -> BuiltGame:
    """F1 ``rpy_readable``: loose ``.rpy`` + ``.rpyc``, local and global (+ ``sync/``) saves."""
    spec = GameSpec(
        dir_name="Readable Game 1.0",
        exe="ReadableGame",
        stmts=options_stmts(
            name="Readable Game",
            version="1.0",
            build_name="ReadableGame",
            save_directory="ReadableGame-1600000001",
        ),
        save_directory="ReadableGame-1600000001",
        style="8.4",
        engine_version="8.4.1.25072401",
    )
    return build_game(games_root, spec, saves_root)


def build_f2(games_root: Path, saves_root: Path) -> BuiltGame:
    """F2 ``rpyc_only_wrapped``: wrapper folder, only ``.rpyc`` + ``archive.rpa``, decoy dir."""
    spec = GameSpec(
        dir_name="Inner'sGame-0.2-pc",
        exe="Inner'sGame",
        stmts=options_stmts(
            name="Inner's Game Beta",
            version="0.2",
            build_name="Inner'sGame",
            save_directory="InnerGame-1637695238",
        ),
        save_directory="InnerGame-1637695238",
        loose_rpy=False,
        rpa_scripts=True,
        local_saves=2,
    )
    built = build_game(games_root / "InnerGame-0.2-pc", spec, saves_root)
    decoy = [Define("gui", "text_size", "22"), Define("gui", "name_text_size", "30")]
    (built.gamedir / "game").mkdir()
    (built.gamedir / "game" / "gui.rpyc").write_bytes(rpyc_bytes(decoy, "game/game/gui.rpy"))
    # A translation inside the archive must be ignored (tl/ is skipped).
    tl_text, _ = render_rpy([Define("config", "save_directory", '"WrongFromTranslation"')])
    archive = built.gamedir / "archive.rpa"
    members = {
        "options.rpy": render_rpy(spec.stmts)[0].encode("utf-8"),
        "script.rpy": render_rpy(script_stmts())[0].encode("utf-8"),
        "images/bg room.png": b"\x89PNG\r\n\x1a\nsynthetic image",
        "tl/RU/options.rpy": tl_text.encode("utf-8"),
    }
    archive.write_bytes(rpa_bytes(members))
    return built


@dataclass
class SavesRootMisc:
    unlinked: dict[str, str | None]
    excluded: list[str]


def build_f8(saves_root: Path) -> SavesRootMisc:
    """F8 ``saves_root_misc``: engine/launcher folders plus two orphaned save folders."""
    write_text(saves_root / "tokens" / "security_keys.txt", "signing-key SYNTHETIC-NOT-A-KEY\n")
    write_text(saves_root / "tokens" / "upgraded.txt", "Orphan-1500000000\n")
    write_files(saves_root / "persistent", {"launcher.renpy.org": persistent_bytes(7)})
    write_files(saves_root / "launcher-4", {"persistent": persistent_bytes(8)})
    orphan = {"1-1-LT1.save": save_bytes("0.7.2", seed=3), "persistent": persistent_bytes(3)}
    write_files(saves_root / "Orphan-1500000000", orphan)
    write_files(saves_root / "OrphanTwo", {"persistent": persistent_bytes(4)})
    return SavesRootMisc(
        unlinked={"Orphan-1500000000": "0.7.2", "OrphanTwo": None},
        excluded=["launcher-4", "persistent", "tokens"],
    )


def simple_spec(dir_name: str, exe: str, save_directory: str | None, **kwargs: object) -> GameSpec:
    """A spec whose options define ``config.name = dir_name``-ish values."""
    name = str(kwargs.pop("name", dir_name))
    version = str(kwargs.pop("version", "1.0"))
    extra = kwargs.pop("extra", None)
    stmts = options_stmts(
        name=name, version=version, build_name=exe, save_directory=save_directory, extra=extra
    )
    return GameSpec(dir_name, exe, stmts, save_directory, **kwargs)


def build_f3(games_root: Path, saves_root: Path) -> BuiltGame:
    """F3 ``no_saves_yet``: complete metadata, no local ``saves/``, no global folder."""
    spec = simple_spec("Fresh Game", "FreshGame", "FreshGame-1700000000", local_saves=0)
    return build_game(games_root, spec, saves_root)


def build_f4(games_root: Path, saves_root: Path) -> list[BuiltGame]:
    """F4 ``shared_global_two_versions``: two installs, same ``save_directory`` and name."""
    v1 = simple_spec("GameA-v1", "GameA", "GameA-1500000000", name="Game A", local_saves=2)
    v2 = simple_spec("GameA-v2", "GameA", "GameA-1500000000", name="Game A", version="2.0")
    return [build_game(games_root, v1, saves_root), build_game(games_root, v2, saves_root)]


def build_f4b(games_root: Path, saves_root: Path) -> list[BuiltGame]:
    """F4b ``same_dir_diff_name``: two different games use one global folder. A CONFLICT
    until 0.7.0; since 0.8.0 (D48) two CONFIRMED games that both back the folder up."""
    alpha = simple_spec("Alpha Story", "AlphaStory", "SharedSaves")
    beta = simple_spec("Beta Story", "BetaStory", "SharedSaves")
    return [build_game(games_root, alpha, saves_root), build_game(games_root, beta, saves_root)]


DYNAMIC_SAVEDIR = 'import os\nconfig.savedir = os.path.join(config.basedir, "saves")'


def build_f5(games_root: Path, saves_root: Path) -> BuiltGame:
    """F5 ``dynamic_savedir``: ``python early`` assigns ``config.savedir`` from code."""
    extra = [PythonBlock(DYNAMIC_SAVEDIR, early=True)]
    spec = simple_spec("Dynamic Game", "DynamicGame", "DynamicGame-1600000005", extra=extra)
    return build_game(games_root, spec, saves_root)


def build_f6(games_root: Path, saves_root: Path) -> BuiltGame:
    """F6 ``no_metadata_name_match``: no options script; a name-alike folder in saves_root."""
    spec = GameSpec("Nameless Quest", "NamelessQuest", save_directory=None, options=False)
    built = build_game(games_root, spec, saves_root)
    write_files(saves_root / "NamelessQuest-123456", save_set(2, seed=60))
    return built


