def build_f18(
    games_root: Path, saves_root: Path, names: tuple[str | None, str | None] = (None, None)
) -> list[BuiltGame]:
    """F18 ``seasons_share_save_directory`` (D48): two seasons of one work, one global save
    directory (``shared_seasons``), the same ``build.name``; by default neither defines
    ``config.name``, as MILFs of Sunville does, so both are called ``SharedSeasons``."""
    seasons = (("Season One", "Season-1-Extra"), ("Season Two", "Season2-v9.00"))
    built = []
    for index, ((folder, version), name) in enumerate(zip(seasons, names, strict=True)):
        stmts = options_stmts(
            name=name, version=version, build_name="SharedSeasons", save_directory="shared_seasons"
        )
        spec = GameSpec(
            folder, "SharedSeasons", stmts, "shared_seasons", local_saves=2 + index, global_saves=3
        )
        built.append(build_game(games_root, spec, saves_root))
    return built


def build_f19(games_root: Path, saves_root: Path, *, one_script: bool = True) -> BuiltGame:
    """F19 ``split_save_directory``: options name the game but no save directory, and other
    scripts name different ones. Since 0.10.0 (D60 2) the full parse stops after the first
    script that names one, so the CONFLICT left (6.4 rule 2) is a script that names two
    (``one_script``; or different ``config.extra_savedirs`` lists in the scripts read before
    the stop); with two scripts the first of them wins and the other is not read."""
    options = options_stmts(name="Split Story", build_name="SplitStory", save_directory=None)
    split_a = Define("config", "save_directory", '"Split-A"')
    split_b = Define("config", "save_directory", '"Split-B"')
    extra = (
        {"saves_split": [split_a, split_b]}
        if one_script
        else {"saves_a": [split_a], "saves_b": [split_b]}
    )
    spec = GameSpec("Split Story", "SplitStory", options, "Split-A", extra_scripts=extra)
    return build_game(games_root, spec, saves_root)


def build_f19b(games_root: Path, saves_root: Path) -> BuiltGame:
    """F19b ``options_win``: ``options.rpyc`` says Split-B, a stale ``options.rpy`` Split-A,
    and another script Split-C. Options win (D52 1): the compiled form; neither the stale
    ``.rpy`` (it has a readable ``.rpyc``) nor the other script is read."""
    rpy = options_stmts(name="Split Story", build_name="SplitStory", save_directory="Split-A")
    rpyc = options_stmts(name="Split Story", build_name="SplitStory", save_directory="Split-B")
    extra = {"elsewhere": [Define("config", "save_directory", '"Split-C"')]}
    spec = GameSpec(
        "Split Story", "SplitStory", rpy, "Split-A", rpyc_stmts=rpyc, extra_scripts=extra
    )
    return build_game(games_root, spec, saves_root)


def build_f20(games_root: Path, saves_root: Path, version: str = "3.0") -> BuiltGame:
    """F20 ``renamed_archive`` (D53 1): every script is in an RPA archive called
    ``archive.liu``; nothing in ``game/`` ends in .rpy, .rpyc or .rpa."""
    spec = simple_spec(
        "Renamed Archive",
        "RenamedArchive",
        "RenamedArchive-1600000020",
        loose_rpy=False,
        loose_rpyc=False,
        rpa_scripts=True,
        rpa_name="archive.liu",
    )
    built = build_game(games_root, spec, saves_root)
    if version != "3.0":
        archive = {"options.rpy": render_rpy(spec.stmts)[0].encode("utf-8")}
        (built.gamedir / "archive.liu").write_bytes(rpa_bytes(archive, version=version))
    return built


def build_f21(games_root: Path, saves_root: Path) -> BuiltGame:
    """F21 ``no_scripts`` (D53 2, like CityDevilRestart): the scripts are packed in a format
    of the game's own (``game/archive.liu`` that is not an RPA, a ``liuli/`` folder beside
    it); ``game/saves`` has saves and a global folder only matches by name."""
    spec = GameSpec(
        "City Restart", "CityRestart", save_directory=None, options=False,
        loose_rpy=False, loose_rpyc=False,
    )  # fmt: skip
    built = build_game(games_root, spec, saves_root)
    (built.gamedir / "archive.liu").write_bytes(b"LIULI\x00\x01 not an RPA archive")
    write_text(built.root / "liuli" / "loader.py", "# a packer's loader; never executed\n")
    write_files(saves_root / "CityRestart-1600000021", save_set(2, seed=210))
    return built


