def build_many_scripts(
    games_root: Path,
    saves_root: Path,
    *,
    options: bool = True,
    second: bool = False,
    options_dir: str = "",
) -> BuiltGame:
    """The performance game (D52): 700 scripts (as .rpy and .rpyc) beside options. With
    ``options=False`` the options define no save directory and the last script does, so the
    scan reads everything; with ``second`` the script read second does (``00_define``, D60
    2); ``options_dir`` puts the options in that folder below ``game/`` (D60 1)."""
    named = options and not second
    stmts = options_stmts(
        name="Many Scripts",
        build_name="ManyScripts",
        save_directory="ManyScripts-1600000700" if named else None,
    )
    define = [Define("config", "save_directory", '"ManyScripts-1600000700"')]
    extra = {} if named else ({"00_define": define} if second else {"zz_late": define})
    spec = GameSpec(
        "Many Scripts", "ManyScripts", stmts, "ManyScripts-1600000700",
        script_count=698, extra_scripts=extra, options_dir=options_dir,
    )  # fmt: skip
    return build_game(games_root, spec, saves_root)


def reinstall_copy(root: Path, dest: Path) -> Path:
    """The same game freshly unpacked somewhere else: its folder without any ``saves``."""
    shutil.copytree(root, dest, ignore=shutil.ignore_patterns("saves"))
    return dest


FILETIME_EPOCH = 116_444_736_000_000_000


def recycle_info_bytes(original: str, size: int, deleted_ns: int, *, version: int = 2) -> bytes:
    """An ``$I`` file as Windows writes it (D41): version 2 by default, or version 1."""
    filetime = deleted_ns // 100 + FILETIME_EPOCH
    head = struct.pack("<qqq", version, size, filetime)
    text = (original + "\0").encode("utf-16-le")
    if version == 2:
        return head + struct.pack("<i", len(original) + 1) + text
    return head + text.ljust(520, b"\0")


def recycle_like_windows(path: Path, bin_folder: Path, deleted_ns: int) -> tuple[Path, Path]:
    """Move ``path`` into a synthetic ``$RECYCLE.BIN\\<SID>`` folder as ``$R…`` with its
    ``$I…`` beside it, the way the shell recycles a folder; returns ``(info, data)``."""
    bin_folder.mkdir(parents=True, exist_ok=True)
    while True:
        name = "".join(random.choices("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", k=6)) + path.suffix
        info, data = bin_folder / f"$I{name}", bin_folder / f"$R{name}"
        if not info.exists() and not data.exists():
            break
    size = sum(f.stat().st_size for f in path.rglob("*") if f.is_file()) if path.is_dir() else 0
    shutil.move(str(path), str(data))
    info.write_bytes(recycle_info_bytes(str(path), size, deleted_ns))
    return info, data


def stored(repo: Any, game_id: str, snapshot_id: str, source_id: str, path: str = "") -> Path:
    """Where a snapshot keeps a source's file (its folder when ``path`` is empty): the
    readable layout of 0.11.0 (D67 3), ``data/<source>`` in an older snapshot."""
    from enginesave import layout

    snapshot = repo.snapshot_dir(game_id, snapshot_id)
    folder = layout.source_data_dir(snapshot, repo.load_manifest(game_id, snapshot_id), source_id)
    return folder.joinpath(*path.split("/")) if path else folder


def to_v1(repo: Any, game_id: str, snapshot_id: str) -> None:
    """Turn a snapshot into the 0.1.0 layout: plain copies in ``data/<source>``, manifest
    format 1 without ``storage``."""
    from enginesave import layout

    snapshot = repo.snapshot_dir(game_id, snapshot_id)
    manifest_path = snapshot / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    files: dict[Path, bytes] = {}
    for item in manifest["files"]:
        path = layout.snapshot_file_path(snapshot, manifest, item)
        files[snapshot / "data" / item["source_id"] / Path(*item["path"].split("/"))] = (
            path.read_bytes()
        )
    shutil.rmtree(snapshot / "data")
    for path, data in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    manifest["format_version"] = 1
    manifest.pop("storage", None)
    for source in manifest["sources"]:
        source["data_dir"] = f"data/{source['source_id']}"
    manifest_path.write_text(json.dumps(manifest), encoding="utf-8")


def make_junction(link: Path, target: Path) -> bool:
    """Create a directory junction (Windows) or symlink; ``False`` when not possible here."""
    try:
        if sys.platform == "win32":
            import _winapi

            _winapi.CreateJunction(str(target), str(link))
        else:
            link.symlink_to(target, target_is_directory=True)
    except (OSError, AttributeError, ImportError):
        return False
    return True
